    reset_token = auth_cfg.get("reset_password")
    if not isinstance(reset_token, str) or not reset_token.strip():
        pytest.skip("No reset_password token provided in config.auth.reset_password")

    assert isinstance(scenarios, list) and scenarios, "No scenarios available for success tests"

    for idx, scn in enumerate(scenarios, start=1):
        provider = _resolve_provider(scn, data, config)
        if not provider:
            pytest.skip("Missing auth_provider in scenario/config (test_data.auth_provider)")
        endpoint = _ENDPOINT.replace("{auth_provider}", provider)

