        try:
            vr = _VALIDATOR.validate_json(payload, "input")
            assert vr.get("valid") is True, f"Request payload failed schema validation: {vr}"
        except Exception:
            # No named schema available; proceed without request-body validation
            pass

        headers = _build_headers_with_token(reset_token)

        resp = api_client.post(endpoint, json=payload, headers=headers)

        expected_status = scn.get("statusCode", 200)
        assert resp.status_code == expected_status, f"[Scenario {idx}] Expected {expected_status}, got {resp.status_code}. Body: {resp.text}"

        vrsp = _VALIDATOR.validate_schema_by_response(_ENDPOINT, _METHOD, str(resp.status_code), resp)
        assert vrsp.get("valid") is True, f"[Scenario {idx}] Response schema invalid: {vrsp}. Body: {resp.text}"

        # Validate required field 'success' for 200 response
        if resp.status_code == 200:
            ctype = resp.headers.get("Content-Type", "").lower()
            if "json" in ctype:
                body = resp.json()
                assert isinstance(body, dict), f"[Scenario {idx}] Expected JSON object, got: {type(body)}"
